/// The items below are pub(crate).
/// Files under `directory` whose names match one filter, as paths relative to `directory`, sorted.
/// No filter means every file. Hidden entries start with a dot.
fn directory_files(directory: &std::path::Path, filters: &[String], recursive: bool, hidden: bool, symlinks: bool) -> Result<Vec<std::path::PathBuf>, ProjectError>
/// `*` matches any run, `?` matches one scalar. The match is case sensitive and covers the whole name.
fn wildcard_match(pattern: &str, name: &str) -> bool
